:::tip
vseed는 손실 없는 직렬화를 지원하므로, 플랫폼 간 전송과 복사/붙여넣기가 가능하며 Node.js 환경과 브라우저 환경 모두에서 builder를 통해 완전한 spec을 직접 얻을 수 있습니다
:::

아래 예제는 VSeed 설정을 JSON 문자열로 직렬화하는 방법(복사 시뮬레이션)과 JSON 문자열을 역직렬화하여 렌더링하는 방법(붙여넣기 시뮬레이션)을 보여줍니다.

registerAll()

const Demo = () => {
  const [vseed, setVSeed] = useState()
  const ref = useRef()
  const chartRef = useRef()
  const vseed1: VSeed = {
    chartType: 'line',
    dataset: [
      { date: '2019', profit: 10, sales: 100 },
      { date: '2020', profit: 30, sales: 200 },
      { date: '2021', profit: 30, sales: 300 },
      { date: '2022', profit: 50, sales: 400 },
      { date: '2023', profit: 40, sales: 500 },
    ],
  }

  const vseed2: VSeed = {
    chartType: 'bar',
    dataset: [
      { date: '2019', profit: 10, sales: 100 },
      { date: '2020', profit: 30, sales: 200 },
      { date: '2021', profit: 30, sales: 300 },
      { date: '2022', profit: 50, sales: 400 },
      { date: '2023', profit: 40, sales: 500 },
    ],
  }

  const copyVSeed1 = async () => {
    await navigator.clipboard.writeText(JSON.stringify(vseed1))
  }
  const copyVSeed2 = async () => {
    await navigator.clipboard.writeText(JSON.stringify(vseed2))
  }

  const paste = async () => {
    try {
      if (chartRef.current) {
        chartRef.current.release()
      }
      const clipboardText = await navigator.clipboard.readText()
      const parsedVSeed = JSON.parse(clipboardText)

      const builder = Builder.from(parsedVSeed)
      const advancedVSeed = builder.buildAdvanced()
      const spec = builder.buildSpec(advancedVSeed)
      const vchart = new VChart(spec, { dom: ref.current })
      vchart.renderSync()

      chartRef.current = vchart
    } catch (error) {
      console.log('debug', error)
      alert('클립보드에서 내용을 읽는 중 오류가 발생했습니다')
    }
  }

  return (
    <div style={{ display: 'flex' }}>
      <div style={{ width: 100 }}>
        <button onClick={copyVSeed1} style={{ width: 100, marginBottom: 4 }}>
          copy demo1
        </button>
        <button onClick={copyVSeed2} style={{ width: 100, marginBottom: 4 }}>
          copy demo2
        </button>
        <button onClick={paste} style={{ width: 100 }}>
          paste
        </button>
      </div>

      <div ref={ref} style={{ height: 260, width: 'calc(100% - 100px)' }}></div>
    </div>
  )
}

export default Demo

축 정렬과 범례 정렬

VSeed는 편리한 정렬 설정을 제공합니다.

sort: 축 데이터의 정렬 규칙을 설정하는 데 사용하며, 정렬 필드 orderBy와 정렬 순서 order를 지정할 수 있습니다.

sortLegend: 범례의 정렬 순서를 설정하는 데 사용합니다.

registerAll()

const Demo = () => {
  const ref = useRef<HTMLDivElement>(null)
  const [order, setOrder] = useState('asc')
  const [orderBy, setOrderBy] = useState('date')
  const orderList = ['desc', 'asc']
  const orderByList = ['date', 'profit', 'sales']

  useEffect(() => {
    if (!ref.current) {
      return
    }

    const vseed: VSeed = {
      chartType: 'barParallel',
      dataset: [
        { date: '2019', profit: 10, sales: 100 },
        { date: '2020', profit: 30, sales: 200 },
        { date: '2021', profit: 30, sales: 300 },
        { date: '2022', profit: 50, sales: 400 },
        { date: '2023', profit: 40, sales: 500 },
      ],
      sort: {
        order,
        orderBy,
      },
      sortLegend: {
        order,
      },
    }
    const builder = Builder.from(vseed)
    const spec = builder.build()
    console.log(builder.advancedVSeed.analysis)
    if (isTable(vseed)) {
      const tableInstance = new ListTable(ref.current, spec)
      return () => tableInstance.release()
    } else if (isPivotTable(vseed)) {
      const tableInstance = new PivotTable(ref.current, spec)
      return () => tableInstance.release()
    } else {
      const vchart = new VChart(spec, { dom: ref.current })
      vchart.renderSync()
      return () => vchart.release()
    }
  }, [orderBy, order])

  return (
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      <div>
        {orderList.map((d) => {
          return (
            <span key={d} style={{ margin: '0 2px 0 0' }}>
              <button
                onClick={() => setOrder(d)}
                style={{ fontSize: 10, padding: '0 2px', border: '1px solid #cccccc' }}
              >
                {d}
              </button>
            </span>
          )
        })}
      </div>
      <div>
        {orderByList.map((d) => {
          return (
            <span key={d} style={{ margin: '0 2px 0 0' }}>
              <button
                onClick={() => setOrderBy(d)}
                style={{ fontSize: 10, padding: '0 2px', border: '1px solid #cccccc' }}
              >
                {d}
              </button>
            </span>
          )
        })}
      </div>
      <div ref={ref} style={{ height: 260, width: '100%' }}></div>
    </div>
  )
}

